/* ===== agent-host-coordinates.js ===== */
/**
 * Agent preview / send / SSE 共用的宿主坐标（scene-first）。
 * 与后端 `BridgePromptRequest` 字段对齐。
 */
(function (g) {
  "use strict";

  const HOST_RUNTIME_PROTOCOL_SCHEMA = "mei-host-runtime-protocol-v1";
  const HOST_RUNTIME_CONTRACT_SCHEMA = "mei-host-runtime-contract-v1";

  function safeObject(value) {
    return value && typeof value === "object" && !Array.isArray(value) ? value : null;
  }

  function resolveHostSurface(routeMode) {
    return String(routeMode || "").trim().toLowerCase() === "access"
      ? "access_host"
      : "authoring_host";
  }

  function buildHostProtocol(routeMode, mode) {
    return {
      schema: HOST_RUNTIME_PROTOCOL_SCHEMA,
      surface: resolveHostSurface(routeMode),
      route_mode: String(routeMode || "manage"),
      mode: String(mode || "build"),
    };
  }

  function resolveBrowserContext(api, options) {
    const opts = safeObject(options) || {};
    if (safeObject(opts.browserContext)) return opts.browserContext;
    if (api && typeof api.collectBrowserContext === "function") {
      const ctx = api.collectBrowserContext();
      if (safeObject(ctx)) return ctx;
    }
    return null;
  }

  function buildAgentHostCoordinates(api, options) {
    const root = api.root;
    const state = api.state || {};
    const opts = safeObject(options) || {};
    const ext =
      typeof g !== "undefined" && g.MeiAgentScopeParams ? g.MeiAgentScopeParams : null;
    const route = api.normalizeRouteMode(root.dataset.mode);
    const mode = api.normalizeAgentMode(state.agentMode);
    let resourceVisibility = String(opts.resourceVisibility || "").trim();
    if (!resourceVisibility) {
      if (ext && typeof ext.effectiveResourceVisibility === "function") {
        const sel = document.getElementById("author-resource-visibility-select");
        const rawSel = sel && "value" in sel ? String(sel.value || "").trim() : "";
        resourceVisibility = ext.effectiveResourceVisibility(rawSel, route, mode);
      } else if (api.CTX && typeof api.CTX.currentResourceVisibility === "function") {
        resourceVisibility = api.CTX.currentResourceVisibility();
      }
    }
    const coords = {
      app_id: String(root.dataset.app || api.currentAppKey() || ""),
      scene_id: String(api.currentSceneId() || ""),
      target_file: String(api.currentTargetKey() || ""),
      route_mode: route,
      mode: mode,
      resource_visibility: resourceVisibility,
      host_protocol: buildHostProtocol(route, mode),
      host_contract_schema: HOST_RUNTIME_CONTRACT_SCHEMA,
    };
    const browserContext = resolveBrowserContext(api, opts);
    if (browserContext) {
      coords.browser_context = browserContext;
    }
    return coords;
  }

  function applyToUrlSearchParams(params, coords) {
    if (!params || !coords) return params;
    if (coords.app_id) params.set("app_id", coords.app_id);
    if (coords.target_file) params.set("target_file", coords.target_file);
    params.set("route_mode", coords.route_mode || "access");
    params.set("mode", coords.mode || "build");
    if (coords.resource_visibility) {
      params.set("resource_visibility", coords.resource_visibility);
    }
    if (coords.scene_id) params.set("scene_id", coords.scene_id);
    if (coords.browser_context && typeof coords.browser_context === "object") {
      try {
        params.set("browser_context", JSON.stringify(coords.browser_context));
      } catch (_) {}
    }
    if (coords.host_protocol && typeof coords.host_protocol === "object") {
      try {
        params.set("host_protocol", JSON.stringify(coords.host_protocol));
      } catch (_) {}
    }
    if (coords.host_contract_schema) {
      params.set("host_contract_schema", String(coords.host_contract_schema));
    }
    return params;
  }

  function buildPromptRequestBody(api, text, options) {
    const coords = buildAgentHostCoordinates(api, options);
    const body = {
      text: String(text || ""),
      app_id: coords.app_id,
      scene_id: coords.scene_id,
      target_file: coords.target_file,
      mode: coords.mode,
      route_mode: coords.route_mode,
      agent: coords.mode,
      resource_visibility: coords.resource_visibility,
    };
    if (coords.browser_context && typeof coords.browser_context === "object") {
      body.browser_context = coords.browser_context;
    }
    if (coords.host_protocol && typeof coords.host_protocol === "object") {
      body.host_protocol = coords.host_protocol;
    }
    if (coords.host_contract_schema) {
      body.host_contract_schema = String(coords.host_contract_schema);
    }
    return body;
  }

  g.MeiAgentHostCoordinates = {
    build: buildAgentHostCoordinates,
    applyToUrlSearchParams: applyToUrlSearchParams,
    buildPromptRequestBody: buildPromptRequestBody,
  };
})(typeof globalThis !== "undefined" ? globalThis : this);

;

/* ===== statusbar.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.statusBarMounted) return;
  boot.statusBarMounted = true;

  function readMeta(name) {
    const node = document.querySelector('meta[name="' + name + '"]');
    return node ? String(node.getAttribute("content") || "").trim() : "";
  }

  function els() {
    return {
      compliance: document.getElementById("mei-status-compliance"),
      hostVersion: document.getElementById("mei-status-host-version"),
    };
  }

  function setChip(node, text, tone, title) {
    if (!node) return;
    node.textContent = text;
    node.title = title || text;
    node.dataset.tone = tone || "neutral";
  }

  function applyComplianceChip() {
    const nodes = els();
    if (!nodes.compliance) return;
    const parts = [
      readMeta("mei-host-icp-record"),
      readMeta("mei-host-psb-record"),
      readMeta("mei-host-copyright"),
    ].filter(Boolean);
    if (!parts.length) {
      nodes.compliance.hidden = true;
      nodes.compliance.textContent = "";
      return;
    }
    nodes.compliance.hidden = false;
    const text = parts.join(" · ");
    setChip(nodes.compliance, text, "neutral", text);
  }

  function applyHostVersionChip() {
    const nodes = els();
    const label = readMeta("mei-host-version-label");
    const version = readMeta("mei-host-version");
    const text = label || (version ? "Mei " + version : "");
    if (!text) return;
    setChip(nodes.hostVersion, text, "neutral", text);
  }

  function start() {
    applyComplianceChip();
    applyHostVersionChip();
  }

  boot.disposeStatusBar = function () {
    boot.statusBarMounted = false;
  };
  start();
})();

;

/* ===== visit-history-panel.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.visitHistoryPanelMounted) return;
  boot.visitHistoryPanelMounted = true;

  const POPOVER_ID = "mei-visit-history-popover";
  const TRIGGER_ID = "mei-visit-history-trigger";

  function store() {
    return window.MeiVisitHistoryStore || null;
  }

  function formatMs(value) {
    const ms = Number(value);
    if (!Number.isFinite(ms) || ms < 0) return "—";
    if (ms < 1000) return `${Math.round(ms)}ms`;
    return `${(ms / 1000).toFixed(2)}s`;
  }

  function formatTime(at) {
    const date = new Date(Number(at) || 0);
    if (Number.isNaN(date.getTime())) return "—";
    return date.toLocaleTimeString("zh-CN", { hour12: false });
  }

  function kindLabel(kind) {
    const api = store();
    if (api && typeof api.kindLabel === "function") {
      return api.kindLabel(kind);
    }
    return String(kind || "访问");
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;");
  }

  function truncate(text, max) {
    const value = String(text || "");
    if (value.length <= max) return value;
    return value.slice(0, Math.max(0, max - 1)) + "…";
  }

  function buildPerfLine(item) {
    const parts = [`渲染 ${formatMs(item.renderMs)}`];
    if (Number(item.apiTotal) > 0 || Number(item.evalMs) > 0) {
      parts.push(`求值 ${formatMs(item.evalMs)}`);
    }
    parts.push(`总计 ${formatMs(item.totalMs)}`);
    return parts.join(" · ");
  }

  function formatRecordForAgent(item) {
    const api = store();
    if (api && typeof api.formatRecordForAgent === "function") {
      return api.formatRecordForAgent(item);
    }
    return JSON.stringify(item, null, 2);
  }

  function formatAllForAgent(items) {
    const api = store();
    if (api && typeof api.formatAllForAgent === "function") {
      return api.formatAllForAgent(items);
    }
    return JSON.stringify(items, null, 2);
  }

  async function copyText(text) {
    const payload = String(text || "");
    if (!payload) return false;
    try {
      if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
        await navigator.clipboard.writeText(payload);
        return true;
      }
    } catch (_) {}
    try {
      const area = document.createElement("textarea");
      area.value = payload;
      area.setAttribute("readonly", "true");
      area.style.position = "fixed";
      area.style.left = "-9999px";
      document.body.appendChild(area);
      area.select();
      const ok = document.execCommand("copy");
      area.remove();
      return ok;
    } catch (_) {
      return false;
    }
  }

  function flashCopyHint(node, ok) {
    if (!(node instanceof HTMLElement)) return;
    const prev = node.textContent;
    node.textContent = ok ? "已复制" : "复制失败";
    node.dataset.tone = ok ? "good" : "danger";
    setTimeout(() => {
      node.textContent = prev;
      node.dataset.tone = "neutral";
    }, 1200);
  }

  function currentAppHeading() {
    const api = store();
    if (!api) return "访问历史";
    const ctx =
      api.collectVisitContext && typeof api.collectVisitContext === "function"
        ? api.collectVisitContext()
        : null;
    const label = String(ctx?.appTitle || ctx?.appId || "").trim();
    return label ? `访问历史 · ${label}` : "访问历史";
  }

  function ensurePopover() {
    let popover = document.getElementById(POPOVER_ID);
    if (popover) return popover;
    popover = document.createElement("div");
    popover.id = POPOVER_ID;
    popover.className = "visit-history-popover";
    popover.setAttribute("hidden", "hidden");
    popover.innerHTML =
      '<div class="visit-history-popover-backdrop" data-visit-history-close="mask"></div>' +
      '<section class="visit-history-popover-panel" role="dialog" aria-label="访问历史">' +
      '<header class="visit-history-popover-head">' +
      '<strong data-visit-history-title="true">访问历史</strong>' +
      '<div class="visit-history-popover-actions">' +
      '<button type="button" class="status-chip visit-history-copy-all" data-visit-history-copy-all="true" data-tone="neutral">复制全部</button>' +
      '<button type="button" class="visit-history-popover-close" data-visit-history-close="button" aria-label="关闭">×</button>' +
      "</div>" +
      "</header>" +
      '<div class="visit-history-popover-body" data-visit-history-list="true"></div>' +
      "</section>";
    popover.addEventListener("click", (event) => {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      if (target.dataset.visitHistoryClose) {
        hidePopover();
        return;
      }
      if (target.dataset.visitHistoryCopyAll === "true") {
        void (async () => {
          const api = store();
          const items = api && typeof api.list === "function" ? api.list() : [];
          const ok = await copyText(formatAllForAgent(items));
          flashCopyHint(target, ok);
        })();
        return;
      }
      const rowCopy = target.closest("[data-visit-history-copy-id]");
      if (rowCopy instanceof HTMLElement && rowCopy.dataset.visitHistoryCopyId) {
        const id = rowCopy.dataset.visitHistoryCopyId;
        const api = store();
        const items = api && typeof api.list === "function" ? api.list() : [];
        const item = items.find((entry) => String(entry.id) === String(id));
        if (!item) return;
        void (async () => {
          const ok = await copyText(formatRecordForAgent(item));
          flashCopyHint(rowCopy, ok);
        })();
      }
    });
    document.body.appendChild(popover);
    return popover;
  }

  function renderList() {
    const popover = ensurePopover();
    const listHost = popover.querySelector("[data-visit-history-list]");
    const titleNode = popover.querySelector("[data-visit-history-title]");
    if (titleNode) titleNode.textContent = currentAppHeading();
    if (!listHost) return;
    const api = store();
    const items = api && typeof api.list === "function" ? api.list() : [];
    if (!items.length) {
      listHost.innerHTML = '<div class="visit-history-empty">暂无访问记录</div>';
      return;
    }
    listHost.innerHTML = items
      .map((item) => {
        const hint = item.uiShown ? "" : '<span class="visit-history-muted">未提示</span>';
        const contextBits = [
          item.workspace ? `工作区 ${truncate(item.workspace, 16)}` : "",
          item.scene ? `场景 ${truncate(item.scene, 24)}` : "",
          item.file ? `文件 ${truncate(item.file, 24)}` : "",
        ].filter(Boolean);
        const contextLine = contextBits.length
          ? `<div class="visit-history-context">${escapeHtml(contextBits.join(" · "))}</div>`
          : "";
        return (
          '<article class="visit-history-row">' +
          '<div class="visit-history-row-top">' +
          `<time>${escapeHtml(formatTime(item.at))}</time>` +
          `<span class="visit-history-kind">${escapeHtml(kindLabel(item.kind))}</span>` +
          hint +
          `<button type="button" class="status-chip visit-history-copy-one" data-visit-history-copy-id="${escapeHtml(item.id)}" data-tone="neutral">复制</button>` +
          "</div>" +
          `<div class="visit-history-label" title="${escapeHtml(item.label || item.path || "")}">${escapeHtml(truncate(item.label || item.path || "访问", 48))}</div>` +
          contextLine +
          `<div class="visit-history-perf">${escapeHtml(buildPerfLine(item))}</div>` +
          "</article>"
        );
      })
      .join("");
  }

  function showPopover() {
    const trigger = document.getElementById(TRIGGER_ID);
    if (!trigger) return;
    const popover = ensurePopover();
    renderList();
    popover.removeAttribute("hidden");
    popover.classList.add("is-open");
    const rect = trigger.getBoundingClientRect();
    const panel = popover.querySelector(".visit-history-popover-panel");
    if (panel instanceof HTMLElement) {
      const margin = 10;
      const panelWidth = Math.min(400, Math.max(300, window.innerWidth - margin * 2));
      panel.style.width = `${panelWidth}px`;
      let left = Math.max(margin, rect.left);
      if (left + panelWidth > window.innerWidth - margin) {
        left = Math.max(margin, window.innerWidth - margin - panelWidth);
      }
      panel.style.left = `${Math.round(left)}px`;
      panel.style.bottom = `${Math.round(window.innerHeight - rect.top + 8)}px`;
    }
  }

  function hidePopover() {
    const popover = document.getElementById(POPOVER_ID);
    if (!popover) return;
    popover.setAttribute("hidden", "hidden");
    popover.classList.remove("is-open");
  }

  function togglePopover() {
    const popover = document.getElementById(POPOVER_ID);
    if (popover && popover.classList.contains("is-open")) {
      hidePopover();
      return;
    }
    showPopover();
  }

  function updateTriggerHint() {
    const trigger = document.getElementById(TRIGGER_ID);
    const api = store();
    if (!trigger || !api || typeof api.list !== "function") return;
    const latest = api.list()[0];
    if (!latest) {
      trigger.title = "最近访问与加载耗时";
      return;
    }
    trigger.title = `${kindLabel(latest.kind)} · ${buildPerfLine(latest)}`;
  }

  function bindTrigger() {
    const trigger = document.getElementById(TRIGGER_ID);
    if (!trigger || trigger.dataset.meiVisitHistoryBound === "1") return;
    trigger.dataset.meiVisitHistoryBound = "1";
    trigger.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      togglePopover();
    });
    updateTriggerHint();
  }

  function isAccessMode() {
    return document.body.classList.contains("access-mode") || document.body.classList.contains("app-view");
  }

  function init() {
    if (!isAccessMode()) return;
    bindTrigger();
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") hidePopover();
    });
    document.addEventListener("mei:visit-history-updated", () => {
      updateTriggerHint();
      const popover = document.getElementById(POPOVER_ID);
      if (popover && popover.classList.contains("is-open")) renderList();
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }

  boot.refreshVisitHistoryPanel = function refreshVisitHistoryPanel() {
    bindTrigger();
    updateTriggerHint();
    renderList();
  };
})();

;

/* ===== agent-panel-utils.js ===== */
/**
 * 作者面板共用纯逻辑：在拼接 bundle 中先于 `agent-panel.js` 执行。
 * 挂载 `window.MeiAgentPanelUtils`（escapeHtml / fetchJson / CHAT_CLASS / 路径归一化 / delta 调试行归一化 / 对话轮次归并 / 角色与进度 chip 样式）。
 */
(function () {
  if (window.MeiAgentPanelUtils) return;

  const CHAT_CLASS = {
    messageBase:
      "author-chat-message group grid gap-1 bg-transparent px-0 py-0.5 pl-2 border-l-2 border-l-transparent",
    messageUser: "author-chat-user border-l-blue-400/65",
    messageAssistant: "author-chat-assistant border-l-emerald-400/55",
    messageAssistantReverted: "author-chat-assistant-reverted border-l-slate-400/65",
    messageSystem: "author-chat-system border-l-amber-300/55",
    roleBase: "author-chat-role text-[10px] font-bold tracking-[0.02em] opacity-90",
    roleUser: "text-blue-300",
    roleAssistant: "text-emerald-300",
    roleAssistantReverted: "text-slate-400",
    roleSystem: "text-amber-300",
    head: "author-chat-head flex items-center justify-between gap-2",
    meta:
      "author-chat-meta inline-flex items-center gap-1.5 opacity-0 pointer-events-none transition-opacity group-hover:opacity-100 group-hover:pointer-events-auto",
    time: "author-chat-time whitespace-nowrap text-[10px] text-slate-400",
    copyButton:
      "author-chat-copy-btn agent-copy-btn rounded-full border border-blue-400/30 bg-slate-950/40 px-2 py-0.5 text-[10px] font-bold text-blue-300 transition-colors hover:border-blue-300/70 hover:bg-blue-600/20",
    inlineActions: "author-chat-inline-actions flex flex-wrap gap-2",
    actionButton:
      "author-chat-action-btn agent-action-btn rounded-full border border-blue-300/45 bg-blue-900/30 px-2.5 py-1.5 text-[11px] font-bold text-slate-200 transition-colors hover:border-blue-200/80 hover:bg-blue-600/40",
    round: "author-chat-round grid gap-2",
    empty:
      "author-chat-empty rounded-xl border border-dashed border-slate-600/55 px-4 py-4 text-center text-xs leading-6 text-slate-400",
    block: "author-chat-block grid gap-1 border-none bg-transparent p-0",
    blockDetails: "author-chat-block-details grid gap-1.5",
    blockSummary:
      "author-chat-block-label list-none cursor-pointer text-[11px] font-bold tracking-[0.01em]",
    blockLabel: "author-chat-block-label text-[11px] font-bold tracking-[0.01em]",
    body: "author-chat-body m-0 whitespace-pre-wrap break-words font-mono text-xs leading-6 text-slate-200",
    bodyMarkdown: "author-chat-body author-chat-md text-xs leading-relaxed text-slate-200",
    progressChip:
      "author-progress-chip inline-flex items-center gap-1.5 rounded-full border border-slate-600/60 bg-slate-950/45 px-2 py-0.5 text-[10px] font-bold text-slate-300",
    progressChipRunning: "border-teal-400/50 bg-teal-700/20 text-teal-100",
    progressChipDone: "border-blue-400/50 bg-blue-800/25 text-blue-100",
    progressChipError: "border-red-400/55 bg-red-900/30 text-red-100",
    progressChipPending: "border-amber-400/45 bg-amber-900/25 text-amber-100",
  };

  let agentRequestsBlocked = false;
  let agentRequestsBlockReason = "";
  let agentExpiryTimerId = 0;

  function readHostCapabilities() {
    const raw =
      document.body?.dataset?.meiAuthCapabilities ||
      document.querySelector('meta[name="mei-auth-capabilities"]')?.content ||
      "{}";
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === "object" ? parsed : {};
    } catch (_) {
      return {};
    }
  }

  function isAuthDisabledProfile(caps) {
    return Boolean(
      caps &&
        caps.access_view &&
        caps.config_upload &&
        caps.build_view &&
        caps.access_agent &&
        caps.agent_control &&
        caps.authoring_agent,
    );
  }

  function hasAccessAgentCapability(caps) {
    return Boolean(caps && caps.access_agent !== false);
  }

  function blockReasonForAgentHttpStatus(status) {
    if (status === 401) return "session_expired";
    if (status === 403) return "capability";
    return "";
  }

  function clearAgentExpiryTimer() {
    if (agentExpiryTimerId) {
      clearTimeout(agentExpiryTimerId);
      agentExpiryTimerId = 0;
    }
  }

  function scheduleAgentExpiryStop(expiresAtSeconds) {
    clearAgentExpiryTimer();
    const exp = Number(expiresAtSeconds || 0);
    if (!Number.isFinite(exp) || exp <= 0) return;
    const delayMs = exp * 1000 - Date.now() + 500;
    if (delayMs <= 0) {
      blockAgentRequests("session_expired");
      return;
    }
    agentExpiryTimerId = setTimeout(function () {
      agentExpiryTimerId = 0;
      blockAgentRequests("session_expired");
    }, delayMs);
  }

  function applySessionTimingFromPayload(payload) {
    if (payload && payload.expiresAt && payload.authenticated !== false) {
      scheduleAgentExpiryStop(payload.expiresAt);
      return;
    }
    if (!payload || !payload.authenticated) {
      clearAgentExpiryTimer();
    }
  }

  function shouldUnblockAfterSessionRefresh(reason) {
    return (
      reason === "session_expired" ||
      reason === "unauthenticated" ||
      reason === "session_check_failed" ||
      reason === "session_check_error"
    );
  }

  function onAuthSessionRefreshed(event) {
    const payload = event && event.detail;
    if (agentRequestsBlocked && shouldUnblockAfterSessionRefresh(agentRequestsBlockReason)) {
      unblockAgentRequests();
    }
    applySessionTimingFromPayload(payload);
  }

  document.addEventListener("mei:auth-session-refreshed", onAuthSessionRefreshed);

  function blockAgentRequests(reason) {
    if (agentRequestsBlocked && agentRequestsBlockReason === String(reason || "")) {
      return;
    }
    agentRequestsBlocked = true;
    agentRequestsBlockReason = String(reason || "");
    clearAgentExpiryTimer();
    try {
      document.dispatchEvent(
        new CustomEvent("mei:agent-auth-blocked", {
          detail: { reason: agentRequestsBlockReason },
        }),
      );
    } catch (_) {}
  }

  function unblockAgentRequests() {
    agentRequestsBlocked = false;
    agentRequestsBlockReason = "";
    clearAgentExpiryTimer();
  }

  function areAgentRequestsBlocked() {
    return agentRequestsBlocked;
  }

  function agentRequestsBlockMessage(reason) {
    const key = String(reason || agentRequestsBlockReason || "");
    if (key === "capability") return "当前账号未开通助手访问权限。";
    if (key === "unauthenticated" || key === "session_expired") {
      return "登录已失效，请刷新页面后重新登录再使用助手。";
    }
    if (key === "session_check_failed" || key === "session_check_error") {
      return "无法确认登录状态，助手已暂停请求。";
    }
    return "助手请求已暂停，请刷新页面后重试。";
  }

  async function resolveAgentAuthGate() {
    const caps = readHostCapabilities();
    if (!hasAccessAgentCapability(caps)) {
      return { allowed: false, reason: "capability" };
    }
    if (isAuthDisabledProfile(caps)) {
      return { allowed: true, reason: "auth_disabled" };
    }
    const loggedIn = String(document.body?.dataset?.meiAuthLoggedIn || "").trim();
    if (loggedIn !== "1") {
      return { allowed: false, reason: "unauthenticated" };
    }
    try {
      const response = await fetch("/api/auth/session", { credentials: "same-origin" });
      if (!response.ok) {
        return { allowed: false, reason: "session_check_failed" };
      }
      const payload = await response.json();
      applySessionTimingFromPayload(payload);
      if (!(payload && payload.authenticated)) {
        return { allowed: false, reason: "unauthenticated" };
      }
      const probe = await fetch("/api/agent/config", { credentials: "same-origin" });
      if (probe.status === 401) {
        return { allowed: false, reason: "session_expired" };
      }
      if (probe.status === 403) {
        return { allowed: false, reason: "capability" };
      }
      if (!probe.ok) {
        return { allowed: false, reason: "session_check_failed" };
      }
      return { allowed: true, reason: "authenticated" };
    } catch (_) {
      return { allowed: false, reason: "session_check_error" };
    }
  }

  function shouldBlockAgentUrl(url) {
    const value = String(url || "");
    return value.startsWith("/api/agent/");
  }

  window.MeiAgentPanelUtils = {
    CHAT_CLASS,
    readHostCapabilities,
    resolveAgentAuthGate,
    blockAgentRequests,
    unblockAgentRequests,
    areAgentRequestsBlocked,
    agentRequestsBlockMessage,
    applySessionTimingFromPayload,
    escapeHtml(value) {
      return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;");
    },
    async fetchJson(url, init) {
      if (areAgentRequestsBlocked() && shouldBlockAgentUrl(url)) {
        const error = new Error(agentRequestsBlockMessage());
        error.status = 401;
        error.agentBlocked = true;
        throw error;
      }
      const response = await fetch(url, {
        credentials: "same-origin",
        ...(init || {}),
      });
      if (!response.ok) {
        let detail = "";
        try {
          detail = (await response.text()).trim();
        } catch (_) {}
        const error = new Error(detail || url + " -> " + response.status);
        error.status = response.status;
        const blockReason = blockReasonForAgentHttpStatus(response.status);
        if (blockReason && shouldBlockAgentUrl(url)) {
          blockAgentRequests(blockReason);
        }
        throw error;
      }
      return response.json();
    },
    chatMessageRoleClass(roleRaw, reverted) {
      if (roleRaw === "user") return CHAT_CLASS.messageUser;
      if (roleRaw === "assistant") {
        return reverted ? CHAT_CLASS.messageAssistantReverted : CHAT_CLASS.messageAssistant;
      }
      return CHAT_CLASS.messageSystem;
    },
    chatRoleTextClass(roleRaw, reverted) {
      if (roleRaw === "user") return CHAT_CLASS.roleUser;
      if (roleRaw === "assistant") {
        return reverted ? CHAT_CLASS.roleAssistantReverted : CHAT_CLASS.roleAssistant;
      }
      return CHAT_CLASS.roleSystem;
    },
    chatBlockLabelToneClass(type) {
      const kind = String(type || "text").toLowerCase();
      if (kind === "reasoning") return "text-amber-200";
      if (kind === "tool") return "text-teal-200";
      if (kind === "patch") return "text-orange-200";
      if (kind === "debug") return "text-violet-200";
      if (kind === "diff") return "text-amber-300";
      if (kind === "code") return "text-blue-200";
      return "text-blue-300";
    },
    progressChipClass(status) {
      const kind = String(status || "pending").toLowerCase();
      if (kind === "running") return CHAT_CLASS.progressChip + " " + CHAT_CLASS.progressChipRunning;
      if (kind === "done") return CHAT_CLASS.progressChip + " " + CHAT_CLASS.progressChipDone;
      if (kind === "error") return CHAT_CLASS.progressChip + " " + CHAT_CLASS.progressChipError;
      return CHAT_CLASS.progressChip + " " + CHAT_CLASS.progressChipPending;
    },
    /** 与作者面板路由/路径归一化一致：trim、反斜杠转正斜杠、去 `./` 前缀。 */
    normalizeFilePath(value) {
      return String(value || "")
        .trim()
        .replace(/\\/g, "/")
        .replace(/^\.\/+/, "");
    },
    /** 将扁平 messages 列表按 user/assistant/system 归并为对话轮次（纯函数）。 */
    conversationRounds(messages) {
      const rounds = [];
      let current = null;
      let orphan = 0;
      (Array.isArray(messages) ? messages : []).forEach(function (message) {
        if (!message || typeof message !== "object") return;
        const role = String(message.role || "");
        if (role === "user") {
          current = {
            id: "round-user-" + String(message.id || String(rounds.length)),
            user: message,
            assistants: [],
            system: [],
          };
          rounds.push(current);
          return;
        }
        if (role === "assistant") {
          if (!current) {
            orphan += 1;
            current = {
              id: "round-orphan-" + String(orphan),
              user: null,
              assistants: [],
              system: [],
            };
            rounds.push(current);
          }
          current.assistants.push(message);
          return;
        }
        if (!current) {
          orphan += 1;
          current = {
            id: "round-system-" + String(orphan),
            user: null,
            assistants: [],
            system: [],
          };
          rounds.push(current);
        }
        current.system.push(message);
      });
      return rounds;
    },
    normalizeDeltaDebugRows(rows) {
      const src = Array.isArray(rows) ? rows : [];
      return src
        .map(function (item) {
          if (!item || typeof item !== "object") return null;
          const serverTs = Number(item.serverTs || 0);
          const clientRxTs =
            Number(item.clientRxTs || 0) || Number(item.clientTs || 0);
          const gapRxMs =
            item.gapRxMs != null && Number.isFinite(Number(item.gapRxMs))
              ? Number(item.gapRxMs)
              : item.gapMs != null && Number.isFinite(Number(item.gapMs))
                ? Number(item.gapMs)
                : null;
          const paintTs =
            item.paintTs != null && Number.isFinite(Number(item.paintTs))
              ? Number(item.paintTs)
              : null;
          const gapPaintMs =
            item.gapPaintMs != null && Number.isFinite(Number(item.gapPaintMs))
              ? Number(item.gapPaintMs)
              : null;
          return {
            serverTs: Number.isFinite(serverTs) ? serverTs : 0,
            clientRxTs: Number.isFinite(clientRxTs) ? clientRxTs : 0,
            paintTs: paintTs,
            partId: String(item.partId || ""),
            messageId: String(item.messageId || ""),
            chars: Number(item.chars || 0),
            preview: String(item.preview || ""),
            gapRxMs: gapRxMs,
            gapPaintMs: gapPaintMs,
          };
        })
        .filter(Boolean)
        .slice(0, 120);
    },
  };
})();

